\title{Neural Network-Enabled Codebook Design for Phased Array Calibration with Arbitrary Array Sizes}
\author{Xiangyu Chen, Hao Sun, Weiming Wang, Yuanan Liu, Wei Fan
\thanks{Xiangyu Chen, Weiming Wang, and Yuanan Liu are with Beijing University of Posts and Telecommunications, Beijing 100876, China (e-mail: 2019212267@bupt.edu.cn; wangwm@bupt.edu.cn; yuliu@bupt.edu.cn).}
